import React, { useState } from "react";
import axios from "axios";

const SearchBar = ({ setHomes, homes }) => {
  const [searchParams, setSearchParams] = useState({
    location: "",
    endDate: "",
    maxPersons: "",
    houseType: "",
  });
  const [error, setError] = useState(null);
  const [hasSearched, setHasSearched] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setSearchParams((prev) => ({ ...prev, [name]: value }));
    if (name === "location" && value === "") {
      setHasSearched(false);
    }
  };

  const handleSearch = async () => {
    if (
      !searchParams.location &&
      !searchParams.endDate &&
      !searchParams.maxPersons &&
      !searchParams.houseType
    ) {
      setError("Please fill at least one search field.");
      return;
    }

    setHasSearched(true);
    try {
      const params = new URLSearchParams();
      if (searchParams.location)
        params.append("location", searchParams.location.toLowerCase());
      if (searchParams.endDate) params.append("endDate", searchParams.endDate);
      if (searchParams.maxPersons)
        params.append("maxPersons", searchParams.maxPersons);
      if (searchParams.houseType)
        params.append("houseType", searchParams.houseType);

      const response = await axios.get(
        `http://localhost:5000/search?${params.toString()}`
      );
      if (response.status === 200 && response.data) {
        setHomes(response.data);
        setError(null);
        console.log(
          `Search results: ${response.data.length} houses`,
          response.data
        );
      } else {
        throw new Error("Unexpected response from server");
      }
    } catch (err) {
      console.error("Search failed:", err.response?.data?.error || err.message);
      setError(
        err.response?.data?.error || "Failed to search. Please try again."
      );
      setHomes([]); // Reset homes on failure
    }
  };

  const handleKeyPress = (e) => {
    if (
      e.key === "Enter" &&
      (searchParams.location ||
        searchParams.endDate ||
        searchParams.maxPersons ||
        searchParams.houseType)
    ) {
      handleSearch();
    }
  };

  return (
    <div
      style={{
        padding: "1rem",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: "0.5rem",
      }}
      onKeyPress={handleKeyPress}
    >
      <div
        style={{
          display: "flex",
          gap: "1rem",
          flexWrap: "wrap",
          justifyContent: "center",
          backgroundColor: "rgba(0, 0, 0, 0.6)",
          padding: "1rem",
          borderRadius: "0.3rem",
        }}
      >
        <input
          type="text"
          name="location"
          value={searchParams.location}
          onChange={handleChange}
          placeholder="Search by city..."
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            width: "200px",
            backgroundColor: "#ffffff",
            color: "#000000",
          }}
        />
        <input
          type="date"
          name="endDate"
          value={searchParams.endDate}
          onChange={handleChange}
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            backgroundColor: "#ffffff",
            color: "#000000",
          }}
        />
        <select
          name="maxPersons"
          value={searchParams.maxPersons}
          onChange={handleChange}
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            backgroundColor: "#ffffff",
            color: "#000000",
          }}
        >
          <option value="">Max Persons</option>
          <option value="1">1</option>
          <option value="2">2</option>
          <option value="3">3</option>
          <option value="4">4+</option>
        </select>
        <select
          name="houseType"
          value={searchParams.houseType}
          onChange={handleChange}
          style={{
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "1px solid #ccc",
            backgroundColor: "#ffffff",
            color: "#000000",
          }}
        >
          <option value="">Accommodation Type</option>
          <option value="Apartment">Apartment</option>
          <option value="Villa">Villa</option>
          <option value="House">House</option>
        </select>
        <button
          onClick={handleSearch}
          style={{
            padding: "0.5rem 1rem",
            backgroundColor: "#3b82f6",
            color: "white",
            borderRadius: "0.3rem",
            border: "none",
            cursor: "pointer",
          }}
        >
          Search
        </button>
      </div>
      {error && (
        <div
          style={{
            color: "#ff3333",
            fontSize: "1.2rem",
            marginTop: "0.5rem",
            backgroundColor: "rgba(255, 255, 255, 0.9)",
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "2px solid #ff5555",
          }}
        >
          {error}
        </div>
      )}
      {hasSearched && !error && homes?.length === 0 && (
        <div
          style={{
            color: "#000000",
            fontSize: "1.2rem",
            marginTop: "0.5rem",
            backgroundColor: "rgba(255, 255, 255, 0.9)",
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "2px solid #000000",
          }}
        >
          No homes found in that area.
        </div>
      )}
      {hasSearched && !error && homes?.length > 0 && (
        <div
          style={{
            color: "#000000",
            fontSize: "1.2rem",
            marginTop: "0.5rem",
            backgroundColor: "rgba(255, 255, 255, 0.9)",
            padding: "0.5rem",
            borderRadius: "0.3rem",
            border: "2px solid #000000",
          }}
        >
          Found {homes.length} homes in that area.
        </div>
      )}
    </div>
  );
};

export default SearchBar;
